{
  "headline": "FDA's records trace our supply to a plant classified VAI 51 days after the shortage posting",
  "headline_cites": ["D5"],
  "sentences": [
    {
      "text": "FDA first posted the penicillin G potassium shortage on 2023-04-26 and it remains current as of 2026-10-21.",
      "cites": ["E18", "D8"]
    },
    {
      "text": "Our product label identifies Pharmacia & Upjohn Company LLC (FEI 1810189) as the registered plant.",
      "cites": ["E13"]
    },
    {
      "text": "FDA inspection 1208260 at that plant ended 2023-06-16 and was classified VAI, 51 days after the shortage posting.",
      "cites": ["D5"]
    },
    {
      "text": "The VAI classification letter for that inspection is dated 2024-09-10, 503 days after the posting.",
      "cites": ["D7"]
    },
    {
      "text": "No FDA action at a registered plant is recorded before the 2023-04-26 posting.",
      "cites": ["D5", "D6", "D7"]
    },
    {
      "text": "Corvale East holds 11.6 days of injection and 24.3 days of powder; Corvale General holds 15.4 days of injection and 20.6 days of powder.",
      "cites": ["D1", "D2", "D3", "D4"]
    },
    {
      "text": "The rule‑ranked first option is to buy from Athenex Pharmaceutical Division, LLC, which is not on FDA's shortage list today.",
      "cites": ["D9"]
    }
  ]
}
